/**
 * PocketPlan logo: a pocket with a check mark ("money planned and under control")
 * on a rounded tile. Drawn with theme tokens so it adapts to light and dark.
 * Static copies for the browser tab and app icons live in src/app/icon.svg and
 * public/icons/ (generated by scripts/generate-icons.mjs).
 */

function Mark({ className = "" }: { className?: string }) {
  return (
    <svg viewBox="0 0 32 32" className={className} aria-hidden focusable="false">
      <rect width="32" height="32" rx="8" fill="var(--accent)" />
      <g fill="none" stroke="var(--text-inverse)" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M8 9h16v9c0 4.5-3.6 7-8 8-4.4-1-8-3.5-8-8z" />
        <path d="M8 9l8 4.5L24 9" />
        <path d="M12.5 19.5l2.5 2.2 4.5-4.7" />
      </g>
    </svg>
  );
}

export function Logo({ variant = "full", className = "" }: { variant?: "full" | "mark"; className?: string }) {
  if (variant === "mark") return <Mark className={className} />;
  return (
    <span className={`inline-flex items-center gap-2 ${className}`}>
      <Mark className="size-9" />
      <span className="text-xl font-semibold tracking-tight">
        Pocket<span className="text-accent">Plan</span>
      </span>
    </span>
  );
}
